package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevDept string
var WsRegHours decimal.Decimal
var WsOtHours decimal.Decimal
var WsGross decimal.Decimal
var WsDeptTotal decimal.Decimal
var WsDeptCount int64
var WsGrandTotal decimal.Decimal
var WsGrandCount int64
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var EmpRecVar EmpRec

var empFile *os.File
var empScanner *bufio.Scanner
var empEOF bool

func decimalFromDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// digits only, may contain spaces? treat as 0
	// parse as integer
	d, err := decimal.NewFromString(s)
	if err != nil {
		// fallback: keep only digits
		filtered := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				filtered += string(ch)
			}
		}
		if filtered == "" {
			return decimal.Zero
		}
		d, _ = decimal.NewFromString(filtered)
	}
	return d.Shift(-scale)
}

// storeTruncate applies truncation to scale and overflow (high-order digits dropped)
func storeTruncate(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// truncate toward zero
	d = d.Truncate(scale)
	// overflow modulo
	// mod = 10^(intDigits+scale)
	if intDigits+int(scale) == 0 {
		return decimal.Zero
	}
	mod := decimal.New(1, int32(intDigits)+scale)
	// use absolute modulo for positive and negative separately
	// For COBOL high-order drop, we keep low order digits including sign.
	// For negative, we need to preserve sign after truncation.
	isNeg := d.IsNegative()
	abs := d.Abs()
	// scale to integer
	scaled := abs.Shift(scale) // abs *10^scale, should be integer
	// modulo
	// scaled.Mod(mod) where mod =10^(intDigits+scale)
	rem := scaled.Mod(mod)
	result := rem.Shift(-scale)
	if isNeg && !rem.IsZero() {
		result = result.Neg()
	}
	// ensure scale
	result = result.Truncate(scale)
	return result
}

func storeRound(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	d = d.Round(scale)
	// overflow
	if intDigits+int(scale) == 0 {
		return decimal.Zero
	}
	mod := decimal.New(1, int32(intDigits)+scale)
	isNeg := d.IsNegative()
	abs := d.Abs()
	scaled := abs.Shift(scale)
	rem := scaled.Mod(mod)
	result := rem.Shift(-scale)
	if isNeg && !rem.IsZero() {
		result = result.Neg()
	}
	result = result.Truncate(scale)
	return result
}

// generic edited formatter
func formatEdited(d decimal.Decimal, pic string) string {
	// split at '.'
	dotIdx := strings.Index(pic, ".")
	var intPattern, fracPattern string
	var scale int32
	if dotIdx >= 0 {
		intPattern = pic[:dotIdx]
		fracPattern = pic[dotIdx+1:]
		scale = int32(len(fracPattern))
	} else {
		intPattern = pic
		fracPattern = ""
		scale = 0
	}
	intDigits := 0
	for _, ch := range intPattern {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// truncate/move to scale (COBOL MOVE truncates)
	// For edited formatting we truncate
	dTrunc := d.Truncate(scale)
	// overflow handling: keep low-order digits as per picture
	// Use absolute for formatting, COBOL would handle sign separately (not needed here)
	isNeg := dTrunc.IsNegative()
	abs := dTrunc.Abs()
	// scaled integer for overflow
	scaled := abs.Shift(scale)
	mod := decimal.New(1, int32(intDigits)+scale)
	// if intDigits==0 and scale==0? not
	var rem decimal.Decimal
	if mod.IsZero() {
		rem = scaled
	} else {
		// when intDigits+scale may be large, mod computed via New(1, n) =10^n
		rem = scaled.Mod(mod)
	}
	// intPart and fracPart
	// intPart = rem /10^scale
	intPartDec := rem.Shift(-scale).Truncate(0)
	fracIntDec := rem.Sub(intPartDec.Shift(scale))
	// integer string zero padded
	intStr := intPartDec.String() // integer, no sign
	// Remove possible decimal part (should be integer)
	if dot := strings.Index(intStr, "."); dot >= 0 {
		intStr = intStr[:dot]
	}
	// pad left with zeros
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	} else if len(intStr) > intDigits {
		// overflow already modulo, but just in case keep low order
		intStr = intStr[len(intStr)-intDigits:]
	}
	// frac string
	fracStr := ""
	if scale > 0 {
		fracStrRaw := fracIntDec.String()
		if dot := strings.Index(fracStrRaw, "."); dot >= 0 {
			fracStrRaw = fracStrRaw[:dot]
		}
		// fracIntDec is integer <10^scale
		if len(fracStrRaw) < int(scale) {
			fracStrRaw = strings.Repeat("0", int(scale)-len(fracStrRaw)) + fracStrRaw
		}
		fracStr = fracStrRaw
		if len(fracStr) > int(scale) {
			fracStr = fracStr[len(fracStr)-int(scale):]
		}
	}

	// build intFormatted with suppression
	var b strings.Builder
	suppressed := true
	digitIdx := 0
	for _, ch := range intPattern {
		if ch == 'Z' || ch == '9' {
			digit := byte('0')
			if digitIdx < len(intStr) {
				digit = intStr[digitIdx]
			}
			digitIdx++
			if ch == 'Z' && suppressed && digit == '0' {
				b.WriteByte(' ')
			} else {
				b.WriteByte(digit)
				if digit != '0' {
					suppressed = false
				} else {
					// for '9' zero, we still have displayed a zero; but for suppression
					// the fact that we displayed a zero due to '9' should not keep suppressed true?
					// Actually if digit is '0' and ch=='9', we have now displayed a real zero,
					// but suppressed should remain true only if we haven't seen non-zero.
					// Keeping suppressed true for commas after would be wrong if number is non-zero?
					// However any non-zero would have already set suppressed false.
					// If the whole number is zero, suppressed stays true (commas stay spaces) which is desired.
					// So keep suppressed as is unless digit != '0'
				}
			}
		} else if ch == ',' {
			if suppressed {
				b.WriteByte(' ')
			} else {
				b.WriteByte(',')
			}
		} else {
			b.WriteByte(byte(ch))
		}
	}
	intFormatted := b.String()
	if scale > 0 {
		intFormatted = intFormatted + "." + fracStr
	}
	if isNeg {
		// COBOL would show sign; not needed for this program (no negatives)
		// Prepend minus in front of first digit? Simplified
		intFormatted = "-" + strings.TrimLeft(intFormatted, " ")
	}
	return intFormatted
}

func formatPIC9(n int64, digits int) string {
	s := fmt.Sprintf("%d", n)
	if s[0] == '-' {
		// keep sign? not needed
		s = s[1:]
		// for negative, COBOL would have sign, but ignore
	}
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	} else if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func initStorage() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.Zero
	WsOtHours = decimal.Zero
	WsGross = decimal.Zero
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
	WsGrandTotal = decimal.Zero
	WsGrandCount = 0
	WsHoursEd = strings.Repeat(" ", 5)
	WsRateEd = strings.Repeat(" ", 6)
	WsGrossEd = strings.Repeat(" ", 12)
	WsDeptEd = strings.Repeat(" ", 14)
	WsGrandEd = strings.Repeat(" ", 17)
	EmpRecVar = EmpRec{
		ErId:    strings.Repeat(" ", 5),
		ErDept:  strings.Repeat(" ", 3),
		ErHours: decimal.Zero,
		ErRate:  decimal.Zero,
	}
	empEOF = false
}

func openEmpFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		empEOF = true
		WsEofFlag = "Y"
		return
	}
	empFile = f
	empScanner = bufio.NewScanner(f)
}

func closeEmpFile() {
	if empFile != nil {
		empFile.Close()
	}
}

func READ_PARA() {
	if empScanner == nil {
		WsEofFlag = "Y"
		empEOF = true
		return
	}
	if !empScanner.Scan() {
		WsEofFlag = "Y"
		empEOF = true
		return
	}
	line := empScanner.Text()
	// LINE SEQUENTIAL: pad with spaces on right if shorter than 17
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	// parse
	ErIdRaw := line[0:5]
	ErDeptRaw := line[5:8]
	ErHoursRaw := line[8:12]
	ErRateRaw := line[12:17]

	EmpRecVar.ErId = ErIdRaw
	EmpRecVar.ErDept = ErDeptRaw
	EmpRecVar.ErHours = decimalFromDigits(ErHoursRaw, 1)
	EmpRecVar.ErRate = decimalFromDigits(ErRateRaw, 2)
}

func PROCESS_PARA() {
	if WsFirstFlag == "Y" {
		WsPrevDept = EmpRecVar.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecVar.ErDept != WsPrevDept {
			DEPT_BREAK_PARA()
			WsPrevDept = EmpRecVar.ErDept
		}
	}
	PAY_PARA()
	READ_PARA()
}

func PAY_PARA() {
	// EVALUATE TRUE WHEN ER-HOURS >40
	forty := decimal.NewFromInt(40)
	if EmpRecVar.ErHours.Cmp(forty) > 0 {
		WsRegHours = storeTruncate(decimal.NewFromInt(40), 3, 1)
		// COMPUTE WS-OT-HOURS = ER-HOURS -40 (truncated)
		raw := EmpRecVar.ErHours.Sub(forty)
		WsOtHours = storeTruncate(raw, 3, 1)
	} else {
		WsRegHours = storeTruncate(EmpRecVar.ErHours, 3, 1)
		WsOtHours = storeTruncate(decimal.Zero, 3, 1)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE *1.5
	onePointFive := decimal.NewFromFloat(1.5) // 1.5 is exact
	prod1 := WsRegHours.Mul(EmpRecVar.ErRate)
	prod2 := WsOtHours.Mul(EmpRecVar.ErRate).Mul(onePointFive)
	rawGross := prod1.Add(prod2)
	WsGross = storeRound(rawGross, 7, 2)

	// ADD WS-GROSS TO WS-DEPT-TOTAL
	WsDeptTotal = storeTruncate(WsDeptTotal.Add(WsGross), 9, 2)
	// ADD 1 TO WS-DEPT-COUNT
	wsDeptCountRaw := WsDeptCount + 1
	// overflow: keep low 3 digits
	if wsDeptCountRaw > 999 {
		wsDeptCountRaw = wsDeptCountRaw % 1000
	}
	WsDeptCount = wsDeptCountRaw

	// ADD WS-GROSS TO WS-GRAND-TOTAL
	WsGrandTotal = storeTruncate(WsGrandTotal.Add(WsGross), 11, 2)
	// ADD 1 TO WS-GRAND-COUNT
	wsGrandCountRaw := WsGrandCount + 1
	if wsGrandCountRaw > 99999 {
		wsGrandCountRaw = wsGrandCountRaw % 100000
	}
	WsGrandCount = wsGrandCountRaw

	// MOVE ER-HOURS TO WS-HOURS-ED
	WsHoursEd = formatEdited(EmpRecVar.ErHours, "ZZ9.9")
	// MOVE ER-RATE TO WS-RATE-ED
	WsRateEd = formatEdited(EmpRecVar.ErRate, "ZZ9.99")
	// MOVE WS-GROSS TO WS-GROSS-ED
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")

	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED.
	fmt.Printf("%s %s %s %s %s\n", EmpRecVar.ErId, EmpRecVar.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPT_BREAK_PARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "  DEPT " WS-PREV-DEPT " EMPLOYEES: " WS-DEPT-COUNT " TOTAL: " WS-DEPT-ED
	countStr := formatPIC9(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = storeTruncate(decimal.Zero, 9, 2)
	WsDeptCount = 0
}

func GRAND_PARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatPIC9(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

func main() {
	initStorage()
	openEmpFile()
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	if WsFirstFlag != "Y" {
		DEPT_BREAK_PARA()
	}
	closeEmpFile()
	GRAND_PARA()
}
